def render_field(key):
    label, widget, help_text = FIELDS[key]
    if isinstance(widget, tuple):
        options = []
        for item in widget:
            value, text = item if isinstance(item, tuple) else (item, item)
            options.append(f'<option value="{escape(value, quote=True)}">{escape(text)}</option>')
        field = f'<select id="{key}" aria-label="{escape(label, quote=True)}">{"".join(options)}</select>'
    else:
        attrs = {'inputmode': widget} if isinstance(widget, str) else widget
        attributes = ' '.join(f'{name}="{escape(value or "", quote=True)}"' for name, value in attrs.items())
        field = f'<input id="{key}" {attributes} aria-label="{escape(label, quote=True)}">'
        if attrs.get('type') == 'password':
            toggle = 'toggleCryptoSecret' if key.startswith('CRYPTO_') else 'toggleSecret'
            field = (f'<div class="secret-field">{field}'
                     f'<button type="button" id="{key}_toggle" title="Show or hide key" '
                     f'onclick="{toggle}(\'{key}\')">show</button></div>')
    if key == 'SPORTS_UNIT_SIZE_PCT':
        field += '<div id="sports-unit-size-preview" class="notice">Waiting for the daily bankroll base.</div>'
    heading = escape(label)
    if help_text:
        heading = (f'<div class="field-head"><span>{heading}</span>'
                   f'<span class="field-help" tabindex="0" role="button" '
                   f'aria-label="{escape(label + ": " + help_text, quote=True)}" '
                   f'data-tip="{escape(help_text, quote=True)}">?</span></div>')
    return f'<label data-setting="{key}">{heading}{field}</label>'


def expand_controls(html):
    return re.sub(r'<!-- controls:\s*([A-Z0-9_\s]+?)\s*-->',
                  lambda match: '\n'.join(render_field(key) for key in match[1].split()), html)
